export type Tokens = { accessToken: string; refreshToken: string; expiraEm?: number };
export type Cofre = { ler(): Promise<Tokens | null>; salvar(t: Tokens): Promise<void>; limpar(): Promise<void> };
export class ErroApi extends Error {
  constructor(public readonly http: number, public readonly codigo: string, mensagem: string) { super(mensagem); }
}
export type ResultadoOperacao = { operationId: string; status: 'PENDING' | 'APPLIED' | 'REJECTED' | 'UNKNOWN'; erro?: string; [k: string]: unknown };

/** Credencial nunca trafega em HTTP puro fora do desenvolvimento. */
export const baseSegura = (base: string, desenvolvimento: boolean) => desenvolvimento || base.startsWith('https://') || /^http:\/\/(127\.0\.0\.1|localhost)(:|\/|$)/.test(base);

type Opcoes = { base: string; fetch: typeof fetch; cofre: Cofre; aoSair: () => void };

export function criarCliente({ base, fetch: f, cofre, aoSair }: Opcoes) {
  const url = (p: string) => `${base}/api/app/v1${p}`;
  const JSON_H = { 'content-type': 'application/json' };
  let renovando: Promise<Tokens | null> | null = null;

  const sair = async () => { await cofre.limpar(); aoSair(); };

  /** Devolve null só se o servidor recusou; falha de rede lança e mantém o login. */
  function renovar(): Promise<Tokens | null> {
    renovando ??= (async () => {
      try {
        const atual = await cofre.ler();
        if (!atual) return null;
        const r = await f(url('/auth/refresh'), { method: 'POST', headers: JSON_H, body: JSON.stringify({ refreshToken: atual.refreshToken }) });
        if (r.status === 401) return null;
        if (!r.ok) throw new ErroApi(r.status, 'UNAVAILABLE', 'Servidor indisponível.');
        const novo = await r.json() as Tokens;
        await cofre.salvar(novo);
        return novo;
      } finally { renovando = null; }
    })();
    return renovando;
  }

  const comToken = async (t: Tokens | null, init: RequestInit = {}): Promise<RequestInit> => ({
    ...init, headers: { ...(init.headers as Record<string, string>), ...(t ? { authorization: `Bearer ${t.accessToken}` } : {}) },
  });
  const lerErro = async (r: Response) => {
    const c = await r.json().catch(() => ({})) as { codigo?: string; erro?: string };
    return new ErroApi(r.status, c.codigo ?? 'ERRO', c.erro ?? 'Não foi possível concluir.');
  };

  async function get<T = unknown>(caminho: string): Promise<T> {
    let r = await f(url(caminho), await comToken(await cofre.ler()));
    if (r.status === 401) {
      const novo = await renovar();
      if (!novo) { await sair(); throw new ErroApi(401, 'UNAUTHENTICATED', 'Entre novamente.'); }
      r = await f(url(caminho), await comToken(novo));
    }
    if (!r.ok) throw await lerErro(r);
    return r.json() as Promise<T>;
  }

  return {
    get,
    renovar,
    sair,
    tokenAtual: () => cofre.ler(),
    async entrar(usuario: string, senha: string, deviceId: string) {
      const r = await f(url('/auth/login'), { method: 'POST', headers: JSON_H, body: JSON.stringify({ usuario, senha, deviceId }) });
      if (!r.ok) throw await lerErro(r);
      await cofre.salvar(await r.json() as Tokens);
    },
    async encerrar() {
      const t = await cofre.ler();
      await f(url('/auth/logout'), await comToken(t, { method: 'POST' })).catch(() => null);
      await sair();
    },
    /** Ação simples, sem efeito em prova: mostra o erro do servidor. */
    async postar(caminho: string, corpo: object) {
      const r = await f(url(caminho), await comToken(await cofre.ler(), { method: 'POST', headers: JSON_H, body: JSON.stringify(corpo) }));
      if (!r.ok) throw await lerErro(r);
      return r.json();
    },
    /**
     * Um envio só. Sem resposta confiável o resultado é UNKNOWN: nunca se reenvia sozinho;
     * quem chamou consulta /operations/{id} e reconcilia.
     */
    async enviarOperacao(caminho: string, corpo: { operationId: string } & Record<string, unknown>): Promise<ResultadoOperacao> {
      const desconhecido: ResultadoOperacao = { operationId: corpo.operationId, status: 'UNKNOWN' };
      let r: Response;
      try {
        r = await f(url(caminho), await comToken(await cofre.ler(), { method: 'POST', headers: JSON_H, body: JSON.stringify(corpo) }));
      } catch { return desconhecido; }
      if (r.status >= 500) return desconhecido;
      if (!r.ok) throw await lerErro(r);
      return r.json() as Promise<ResultadoOperacao>;
    },
  };
}
export type Cliente = ReturnType<typeof criarCliente>;
